// Install: npm install @aws-sdk/client-secrets-manager AWS SDK
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const secretsClient = new SecretsManagerClient({
  region: process.env.AWS_REGION || 'us-east-1'
});

// Cache secrets for performance
let cachedSecrets = {};
const CACHE_TTL = 300000; // 5 minutes

async function getSecret(secretName) {
  // Return cached value if fresh
  const now = Date.now();
  if (cachedSecrets[secretName] && cachedSecrets[secretName].expires > now) {
    return cachedSecrets[secretName].value;
  }

  // Fetch from AWS Secrets Manager
  const command = new GetSecretValueCommand({ SecretId: secretName });
  const response = await secretsClient.send(command);

  // Parse secret (support JSON and plain text)
  const secretValue = response.SecretString
    ? JSON.parse(response.SecretString)
    : response.SecretString;

  // Cache the secret
  cachedSecrets[secretName] = {
    value: secretValue,
    expires: now + CACHE_TTL
  };

  return secretValue;
}

