// src/utils/secretRotator.js
const { SecretsManagerClient, GetSecretValueCommand, PutSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const client = new SecretsManagerClient({ region: process.env.AWS_REGION });

async function rotateSecret(secretName) {
  // 1. Get current version
  const describeCmd = new DescribeSecretCommand({ SecretId: secretName });
  const description = await client.send(describeCmd);

  const versions = description.VersionIdsToStages;
  const currentVersion = Object.keys(versions).find(
    key => versions[key].includes('AWSCURRENT')
  );

  // 2. Store old version
  const oldVersionCmd = new GetSecretValueCommand({ 
    SecretId: secretName,
    VersionId: currentVersion
  });
  const oldVersion = await client.send(oldVersionCmd);

  // 3. Rotate by creating new version
  const newSecret = {
    ...JSON.parse(oldVersion.SecretString),
    password: generateNewPassword(),
    apiKey: generateNewApiKey()
  };

  const putCmd = new PutSecretValueCommand({
    SecretId: secretName,
    SecretString: JSON.stringify(newSecret),
    VersionStages: ['AWSPENDING']
  });
  await client.send(putCmd);

  return {
    previousVersion: currentVersion,
    newVersionStages: ['AWSPENDING']
  };
}

