# Security Review of app.js

## Summary
Basic Express application with several critical security vulnerabilities that need immediate attention.

---

## 🔴 CRITICAL VULNERABILITIES

### 1. SQL Injection (CWE-89) - NOT PRESENT
**Status:** ✅ No vulnerabilities found

The application does not interact with databases directly, so SQL injection is not applicable here.

---

### 2. Authentication & Authorization - CRITICAL
**Status:** ❌ GROSSLY INADEQUATE

**Issues:**
- No authentication mechanism exists
- No authorization checks for any endpoints
- Anyone can access all endpoints
- No rate limiting

**Recommendation:**
```javascript
// BEFORE (Vulnerable)
app.get('/users', (req, res) => {
  res.json([...]);
});

// AFTER (Secure)
const auth = require('express-basic-auth');
const rateLimit = require('express-rate-limit');

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later' }
});

// Reset limiter for auth endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Hard limit for auth attempts
  message: { error: 'Account temporarily locked due to multiple failed attempts' }
});

// Apply rate limiting globally
app.use(limiter);

// Protected user endpoint with authentication
app.get('/users', auth({
  users: { 'admin': 'SecurePassword123!' },
  challenge: true
}), (req, res) => {
  // Authorization check could be added here
  // e.g., if (req.auth.user !== 'admin') { return res.status(403).json(...); }
  res.json([...]);
});

// Health endpoint should be public but still rate-limited
app.get('/health', limiter, (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});
```

---

### 3. Cross-Site Scripting (XSS) - MEDIUM
**Status:** ⚠️ POTENTIAL RISK

**Issues:**
- Uses `res.json()` which auto-escapes HTML by default for Express responses
- If you switch to using `res.send()` with untrusted data, XSS could occur

**Recommendation:**
```javascript
// Current implementation is safe due to JSON auto-escaping
// BUT: If you validate user input, make sure to use proper encoding

// Example of proper XSS prevention
const sanitizeHtml = require('sanitize-html');
const rateLimiter = require('express-rate-limit');

const loginLimiter = rateLimiter({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true
});

app.post('/login', loginLimiter, (req, res) => {
  const { username, password } = req.body;

  // Validate and sanitize that input
  const sanitizedUsername = sanitizeHtml(username, {
    allowedTags: [],
    allowedAttributes: {}
  });
  const sanitizedPassword = sanitizeHtml(password, {
    allowedTags: [],
    allowedAttributes: {}
  });

  // Rest of your auth logic...
});
```

---

### 4. Insecure Direct Object References (IDOR) - MEDIUM
**Status:** ❌ VULNERABLE (if extended)

**Issues:**
- Returns all users without any user context
- In a real application, this could allow accessing other users' data based on IDs

**Recommendation:**
```javascript
// BEFORE
app.get('/users', (req, res) => {
  res.json([...]);
});

// AFTER - Add user context and proper authorization
app.get('/users/:id', (req, res, next) => {
  // Validation of ID type and format
  if (!Number.isInteger(parseInt(req.params.id))) {
    return res.status(400).json({ error: 'Invalid user ID format' });
  }

  // Simulated user context (in real app, from session/auth)
  const requestingUser = req.user || { id: null };

  // IDOR Check: User can only see their own data or be an admin
  const isAdmin = requestingUser.role === 'admin';
  const isOwnData = parseInt(req.params.id) === requestingUser.id;

  if (!isAdmin && !isOwnData) {
    return res.status(403).json({ error: 'Unauthorized access' });
  }

  // In real app, fetch only requested user
  const userData = { id: req.params.id, name: 'Alice', email: 'alice@example.com' };
  res.json(userData);
});
```

---

### 5. Path Traversal (CWE-22) - MEDIUM
**Status:** ✅ No vulnerabilities found

The application doesn't access file systems, so path traversal is not applicable.

---

### 6. Sensitive Data Exposure - MEDIUM
**Status:** ❌ CRITICAL

**Issues:**
- Hardcoded usernames and passwords (if you add auth)
- No HTTPS enforcement (production would expose credentials)
- No CORS configuration (could leak data to malicious origins)

**Recommendation:**
```javascript
const helmet = require('helmet');

// Use Helmet for security headers
app.use(helmet({
  contentSecurityPolicy: false, // Change based on your needs
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// Environment-based configuration
const isProduction = process.env.NODE_ENV === 'production';

// Rate limiting as shown above

// Don't expose version info in production
if (isProduction) {
  app.disable('x-powered-by');
}

// Secure CORS configuration
const cors = require('cors');
app.use(cors({
  origin: process.env.CORS_ORIGIN?.split(',') || ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200
}));

// Never expose stack traces in errors
app.use((err, req, res, next) => {
  console.error(err.stack);
  if (isProduction) {
    res.status(err.status || 500).json({ error: 'Internal server error' });
  } else {
    res.status(err.status || 500).json({ error: err.message, stack: err.stack });
  }
});
```

---

### 7. Missing Input Validation - HIGH
**Status:** ❌ CRITICAL

**Issues:**
- No input validation for any endpoints
- Parameters are accepted without validation
- No query parameter validation

**Recommendation:**
```javascript
const { body, param, validationResult } = require('express-validator');

// Validation middleware helper
const validate = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  next();
};

// Basic user ID parameter validation
app.get('/users/:id',
  [param('id')
    .trim()
    .isInt({ min: 1 })
    .withMessage('User ID must be a positive integer')],
  validate,
  (req, res) => {
    res.json({ id: req.params.id });
  }
);

// Example with query parameters
app.get('/search', [
  query('q')
    .trim()
    .isLength({ min: 2, max: 100 })
    .withMessage('Query must be 2-100 characters')
    .escape(), // Prevents XSS in search results
  query('page')
    .optional()
    .isInt({ min: 1 })
    .withMessage('Page must be a positive integer')
    .toInt(),
  validate
], (req, res) => {
  const { q, page } = req.query;
  res.json({ query: q, page: page || 1 });
});

// Example with POST body
app.post('/users',
  [
    body('name')
      .trim()
      .notEmpty()
      .withMessage('Name is required')
      .escape(),
    body('email')
      .trim()
      .notEmpty()
      .withMessage('Email is required')
      .isEmail()
      .withMessage('Invalid email format')
      .normalizeEmail(),
    body('age')
      .optional()
      .isInt({ min: 0, max: 120 })
      .withMessage('Age must be between 0 and 120')
      .toInt()
  ],
  validate,
  (req, res) => {
    res.status(201).json({ user: req.body });
  }
);
```

---

### 8. Broken Access Control - HIGH
**Status:** ❌ VULNERABLE

**Issues:**
- No role-based access control
- Cannot distinguish between different user types
- No endpoint permissions

**Recommendation:**
```javascript
// Custom authorization middleware
const authorize = (...allowedRoles) => (req, res, next) => {
  if (!req.user) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  if (!allowedRoles.includes(req.user.role)) {
    return res.status(403).json({ error: 'Insufficient permissions' });
  }

  next();
};

// Usage example
app.get('/admin/users',
  auth({ users: {}, challenge: true }), // First authenticate
  authorize('admin'), // Then authorize by role
  (req, res) => {
    // Return admin-only data
    res.json([...]);
  }
);

// Protect sensitive endpoints
app.delete('/users/:id',
  auth({ users: {}, challenge: true }),
  authorize('admin'),
  async (req, res, next) => {
    try {
      // Add proper error handling
      const affectedRows = await User.delete(parseInt(req.params.id));
      if (affectedRows === 0) {
        return res.status(404).json({ error: 'User not found' });
      }
      res.status(204).send();
    } catch (error) {
      next(error);
    }
  }
);
```

---

### 9. Broken Authentication (Password Management) - HIGH
**Status:** ❌ VULNERABLE

**Issues:**
- No password hashing (if you add auth)
- No password strength requirements
- No multi-factor authentication options

**Recommendation:**
```javascript
const bcrypt = require('bcrypt');
const jwt = require('jsonwebtoken');

const saltRounds = 10;

// Hash passwords before storing
const hashPassword = async (password) => {
  const salt = await bcrypt.genSalt(saltRounds);
  return await bcrypt.hash(password, salt);
};

// Verify passwords
const comparePassword = async (password, hash) => {
  return await bcrypt.compare(password, hash);
};

// JWT token generation
const generateToken = (user) => {
  return jwt.sign(
