// utils/secrets.js
const { error } = console;

/**
 * Safely access environment variable
 * Validates required variables and doesn't expose in logs
 */
function getSecrets(envVarNames, fatalMissing = true) {
  const secrets = {};
  const missing = [];
  const unsafe = [];

  envVarNames.forEach(varName => {
    const value = process.env[varName];

    if (value === undefined) {
      missing.push(varName);
    } else if (typeof value === 'string' && value.length > 0) {
      secrets[varName] = value;
    } else {
      // Null, empty string, or undefined
      missing.push(varName);
    }
  });

  if (missing.length > 0) {
    if (fatalMissing) {
      error(`❌ Fatal: Missing required environment variables:`, missing);
      process.exit(1);
    } else {
      error(`⚠️  Warning: Missing environment variables (non-fatal):`, missing);
      // Continue with partial secrets object
    }
  }

  // Check for potential secrets in logs
  Object.keys(secrets).forEach(key => {
    if (/password|secret|token|key/i.test(key)) {
      unsafe.push(key);
    }
  });

  // Warn about potentially sensitive keys being accessed
  // In production, consider not logging these at all

  return secrets;
}

