/**
 * Secure Secrets Management for Node.js Application
 *
 * SECURITY CONSIDERATIONS:
 * 1. Never commit secrets to version control
 * 2. Never log secrets or expose them in error messages
 * 3. Prefer environment variables over file-based configs
 * 4. In production, use a secrets manager (AWS Secrets Manager, HashiCorp Vault, etc.)
 */

const fs = require('fs');
const path = require('path');

class SecretLoader {
  constructor(options = {}) {
    this.envFilePaths = options.envFilePaths || [
      `.${options.mode === 'production' ? '.env.production' : '.env.local'}`,
      '.env',
      '.env.test'
    ];
    this.secrets = {};
    this.loaded = false;
  }

  /**
   * Load secrets from environment variables
   * This is the preferred method for loading secrets
   */
  loadFromEnv() {
    const requiredSecrets = [
      'ANTHROPIC_API_KEY',
      'STRIPE_SECRET_KEY',
      'LOGFIRE_TOKEN'
    ];

    this.secrets = { ...process.env };

    // Warn about missing secrets but don't crash in development
    const missing = requiredSecrets.filter(key => !process.env[key]);
    if (missing.length > 0) {
      if (process.env.NODE_ENV === 'production') {
        throw new Error(`Missing required secrets: ${missing.join(', ')}`);
      } else {
        console.warn(`Warning: Missing secrets (development only): ${missing.join(', ')}`);
      }
    }

    return this;
  }

  /**
   * Load secrets from .env file (NOT RECOMMENDED - use environment variables instead)
   * Only for compatibility with existing code
   */
  loadFromFile(filePath, overrideEnv = false) {
    try {
      if (!fs.existsSync(filePath)) {
        console.warn(`Secrets file not found: ${filePath}`);
        return this;
      }

      const envContent = fs.readFileSync(filePath, 'utf8');
      const lines = envContent.split('\n');

      lines.forEach(line => {
        // Skip comments and empty lines
        if (!line || line.startsWith('#') || line.trim().startsWith('#')) {
          return;
        }

        const [key, ...valueParts] = line.split('=');
        const value = valueParts.join('=');

        if (overrideEnv || !process.env[key]) {
          process.env[key] = value;
        }
      });

      this.loaded = true;
      console.log(`Successfully loaded secrets from ${filePath}`);
      return this;
    } catch (error) {
      if (process.env.NODE_ENV === 'production') {
        console.error(`Failed to load secrets from ${filePath}:`, error.message);
        throw error;
      } else {
        console.warn(`Warning: Could not load secrets from ${filePath}:`, error.message);
      }
    }
  }

  /**
   * Get a secret value with secure retrieval
   * @param {string} key - The secret key
   * @param {object} options - Options for secure retrieval
   * @returns {string} The secret value
   */
  get(key, options = {}) {
    const value = this.secrets[key] || process.env[key];

    // SECURITY: Never log secrets
    if (options.log && process.env.NODE_ENV === 'development') {
      const mask = key.includes('KEY') || key.includes('SECRET') || key.includes('PASSWORD')
        ? value.slice(0, 4) + '***'
        : value.slice(0, 8) + '***';
      console.log(`[DEBUG] ${key}=${mask}`);
    }

    return value;
  }

  /**
   * Get a secret value and validate it
   * @param {string} key - The secret key
   * @param {object} validation - Validation options
   * @returns {string} The secret value
   * @throws {Error} If validation fails
   */
  getAndValidate(key, validation = {}) {
    const value = this.get(key);

    if (!value) {
      throw new Error(`Secret ${key} is not set`);
    }

    if (validation.required && !value || value.length === 0) {
      throw new Error(`Secret ${key} is required`);
    }

    if (validation.minLength && value.length < validation.minLength) {
      throw new Error(`Secret ${key} is too short (minimum ${validation.minLength} characters)`);
    }

    if (validation.pattern && !validation.pattern.test(value)) {
      throw new Error(`Secret ${key} does not match the required pattern`);
    }

    return value;
  }

  /**
   * Get all secrets
   * IMPORTANT: In production, consider masking sensitive values
   */
  getAll() {
    if (process.env.NODE_ENV === 'production') {
      return this.maskSensitive(this.secrets);
    }
    return { ...this.secrets };
  }

  /**
   * Mask sensitive values for logging
   * @private
   */
  maskSensitive(secrets) {
    const sensitiveKeys = [
      'PASSWORD', 'SECRET', 'KEY', 'TOKEN', 'API_KEY', 'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY', 'DATABASE_PASSWORD', 'SESSION_SECRET',
      'STRIPE_SECRET_KEY', 'LOGFIRE_TOKEN', 'ANTHROPIC_API_KEY'
    ];

    return Object.keys(secrets).reduce((result, key) => {
      const isSensitive = sensitiveKeys.some(pattern => key.toUpperCase().includes(pattern));
      result[key] = isSensitive
        ? secrets[key].slice(0, 4) + '***'
        : secrets[key];
      return result;
    }, {});
  }

  /**
   * Check if all required secrets are loaded
   * @param {string[]} requiredSecrets - List of required secret keys
   * @returns {boolean} True if all secrets are present
   */
  areRequiredSecretsLoaded(requiredSecrets = []) {
    return requiredSecrets.every(key => {
      const value = this.get(key);
      return value && value.length > 0;
    });
  }
}

// Example usage:
/*
const secrets = new SecretLoader({ mode: process.env.NODE_ENV || 'development' });

try {
  // Only load .env file in non-production environments
  if (process.env.NODE_ENV !== 'production') {
    secrets.loadFromFile('.env');
  }

  // Load environment variables (preferred method)
  secrets.loadFromEnv();

  // Validate required secrets
  const requiredSecrets = [
    'ANTHROPIC_API_KEY',
    'STRIPE_SECRET_KEY',
    'LOGFIRE_TOKEN'
  ];

  if (!secrets.areRequiredSecretsLoaded(requiredSecrets)) {
    throw new Error('Missing required secrets');
  }

  // Get secret with validation
  const apiKey = secrets.getAndValidate('ANTHROPIC_API_KEY', {
    minLength: 20,
    pattern: /^sk-ant-/
  });

  console.log('API Key:', apiKey);

} catch (error) {
  console.error('Failed to load secrets:', error);
  process.exit(1);
}
*/

module.exports = SecretLoader;

