# Create or edit .gitignore
echo ".env.production" >> .gitignore
echo "*.env.local" >> .gitignore
echo "secrets/" >> .gitignore
```

#### 3. Create .env.example
```bash
# .env.example - SDKTS WHAT SECRETS ARE NEEDED (DO NOT KEEP PRIVATE VALUES)
DATABASE_HOST=localhost
DATABASE_PORT=5432
DATABASE_USER=user
DATABASE_PASSWORD=your_password_here
DATABASE_NAME=production

AWS_ACCESS_KEY_ID=your_key_here
AWS_SECRET_ACCESS_KEY=your_secret_here

STRIPE_SECRET_KEY=your_stripe_key_here
STRIPE_WEBHOOK_SECRET=your_webhook_secret_here

ANTHROPIC_API_KEY=your_api_key_here

LOGFIRE_TOKEN=your_logfire_token_here

JWT_SECRET=random_secret_key_at_least_32_chars
LOG_LEVEL=info
PORT=3000
NODE_ENV=development

# CORS settings
APP_URL=http://localhost:3000
```

#### 4. Use Secrets Managers (Production Only)
```
Option A: AWS Secrets Manager
- Centralized secret storage
- Automatic rotation
- Integrated with AWS IAM
- Cost-effective for AWS

Option B: HashiCorp Vault
- Enterprise-grade secret management
- Dynamic secret generation
- Hidden patterns support
- Multi-cloud support

Option C: AWS Parameter Store
- Simpler than Secrets Manager
- Good for non-sensitive configs
- Limited encryption options

Recommendation: AWS Secrets Manager
- Best compatibility with existing keys
- Automatic rotation support
- Modern security features
```

#### 5. Client-Side Secret Validation
```javascript
// Add secrets validation on startup
function validateSecrets() {
  const secrets = {
    JWT_SECRET: process.env.JWT_SECRET,
    DB_PASSWORD: process.env.DB_PASSWORD,
    AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
    STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY
  };

  // Check each secret for adequate complexity
  for (const [name, value] of Object.entries(secrets)) {
    if (!value || value.length < 32) {
      throw new Error(`${name} must be at least 32 characters long`);
    }
  }

  logger.info('All secrets validated successfully');
}

// Call at application start
try {
  validateSecrets();
} catch (err) {
  logger.error('Secrets validation failed:', err.message);
  process.exit(1);
}
```

### Priority 3: Monitoring and Auditing (1 month)

#### 1. Secret Access Logging
```javascript
// Log when secrets are accessed
const secretAccessLogger = {
  logAccess(secretName) {
    if (process.env.NODE_ENV === 'production') {
      logger.warn('Secret accessed', {
        secret: `${secretName}_is_safe`, // Placeholder
        timestamp: new Date().toISOString(),
        ip: req?.ip,
        userAgent: req?.get('user-agent')
      });
    }
  }
};

// Use in your code
secretAccessLogger.logAccess('DATABASE_URL');
secretAccessLogger.logAccess('AWS_SECRET_ACCESS_KEY');
```

#### 2. Periodic Secret Rotation
```javascript
// Add to secrets manager configuration
const aws = require('aws-sdk');

const rotateSecret = async (secretId) => {
  try {
    const secretsManager = new aws.SecretsManager();

    // Rotation requires:
    // 1. Rotation window defined
    // 2. Lambda function for rotation
    // 3. Callback URLs for rotation

    await secretsManager.rotateSecret({
      SecretId: secretId,
      RotationWindowLunchHours: 2, // hours
      RotationRules: {
        AutomaticallyAfterDays: 30,
        AutomaticallyAfterMinutes: 15
      }
    });

    logger.info('Secret rotation initiated:', secretId);
  } catch (err) {
    logger.error('Secret rotation failed:', { secretId, error: err.message });
  }
};
```

#### 3. Secret Freshness Check
```javascript
// Check if secret was recently rotated
async function checkSecretFreshness(secretId) {
  const secret = await secretsManager.describeSecret({ SecretId: secretId });
  const lastRotated = new Date(secret.LastRotatedDate);

  // Flag if not rotated in last 90 days
  const daysSinceRotation = (Date.now() - lastRotated) / (1000 * 60 * 60 * 24);

  if (daysSinceRotation > 90) {
    logger.warn('Secret not rotated:', {
      secretId,
      daysSinceRotation: Math.floor(daysSinceRotation)
    });
  }
}
```

