### 2. Use Subprocess Execution for Database
```javascript
// For high-security environments:
// Spawn a separate process that reads secrets securely
const { spawn } = require('child_process');

function dbQuery(sql) {
  return new Promise((resolve, reject) => {
    const proc = spawn('node', ['scripts/query-secrets.js', sql]);
    let output = '';

    proc.stdout.on('data', (data) => {
      output += data.toString();
    });

    proc.on('close', (code) => {
      if (code !== 0) reject(new Error('Database query failed'));
      else resolve(JSON.parse(output));
    });
  });
}
```

### 3. Multi-Region Secret Replication
```javascript
// For high-availability certificates
async function replicateSecret(secretId, regions) {
  const secret = await secretsManager.getSecretValue({ SecretId: secretId });

  for (const region of regions) {
    await secretsManager.putSecretValue({
      SecretId: secretId,
      SecretString: secret.SecretString,
      Region: region
    });
  }
}
```

